"use client";
import { useUser } from "@clerk/nextjs";
import { useEffect, useState } from "react";

interface NoteObj {
  _id: string;
  title: string;
  content: string;
}

export default function Notelist() {
  const { user, isLoaded } = useUser();
  const [notes, setNotes] = useState<NoteObj[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState({ title: "", content: "" });

  const fetchNotes = async () => {
    if (!user) return;
    try {
      const res = await fetch(
        `http://localhost:2017/noteops/getallnotes/${user.id}`,
      );
      const data = await res.json();
      setNotes(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error("Fetch error:", err);
    }
  };

  useEffect(() => {
    if (isLoaded && user) fetchNotes();
  }, [user, isLoaded]);

  // DELETE FUNCTION
  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure?")) return;
    try {
      await fetch(`http://localhost:2017/noteops/delete/${id}`, {
        method: "DELETE",
      });
      setNotes(notes.filter((n) => n._id !== id));
    } catch (err) {
      console.log("Delete failed", err);
    }
  };

  // EDIT FUNCTIONS
  const startEdit = (note: NoteObj) => {
    setEditingId(note._id);
    setEditForm({ title: note.title, content: note.content });
  };

  const handleUpdate = async (id: string) => {
    // 1. Add this check to satisfy TypeScript
    if (!user) {
      console.error("User not authenticated");
      return;
    }

    try {
      const res = await fetch(`http://localhost:2017/noteops/edit/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...editForm,
          owner: user.id, // Now TypeScript knows 'user' is definitely defined here
        }),
      });

      if (res.ok) {
        setEditingId(null);
        fetchNotes();
      }
    } catch (err) {
      console.log("Update failed", err);
    }
  };
  return (
    <div className="grid grid-cols-1 gap-4 p-4">
      {notes.map((note) => (
        <div key={note._id} className="border p-4 rounded-lg bg-white shadow">
          {editingId === note._id ? (
            <div className="space-y-2">
              <input
                className="w-full border p-1"
                value={editForm.title}
                onChange={(e) =>
                  setEditForm({ ...editForm, title: e.target.value })
                }
              />
              <textarea
                className="w-full border p-1"
                value={editForm.content}
                onChange={(e) =>
                  setEditForm({ ...editForm, content: e.target.value })
                }
              />
              <button
                onClick={() => handleUpdate(note._id)}
                className="bg-green-500 text-white px-3 py-1 mr-2 rounded"
              >
                Save
              </button>
              <button
                onClick={() => setEditingId(null)}
                className="bg-gray-400 text-white px-3 py-1 rounded"
              >
                Cancel
              </button>
            </div>
          ) : (
            <>
              <h2 className="font-bold text-xl">{note.title}</h2>
              <p className="text-gray-600 mb-4">{note.content}</p>
              <div className="flex gap-2">
                <button
                  onClick={() => startEdit(note)}
                  className="text-blue-600 border border-blue-600 px-3 py-1 rounded hover:bg-blue-50"
                >
                  Edit
                </button>
                <button
                  onClick={() => handleDelete(note._id)}
                  className="text-red-600 border border-red-600 px-3 py-1 rounded hover:bg-red-50"
                >
                  Delete
                </button>
              </div>
            </>
          )}
        </div>
      ))}
    </div>
  );
}
